<?php require_once 'functions.php';require_login();$msg='';if(isset($_GET['check'])){$xml=@file_get_contents('https://trends.google.com/trending/rss?geo=IN');if($xml){$sx=@simplexml_load_string($xml);$names=[];if($sx)foreach($sx->channel->item as $item){$name=trim((string)$item->title);if($name!=='')$names[]=$name;} $inventory=array_map(fn($r)=>strtolower(trim($r['name'])),stocks());$missing=[];foreach($names as $n){if(!in_array(strtolower($n),$inventory,true))$missing[]=$n;}foreach(array_unique($missing) as $n){$q=db()->prepare('INSERT IGNORE INTO missing_products(name,checked_at) VALUES(?,NOW())');$q->execute([$n]);}flash('Google Trends RSS checked. Missing terms saved.');}else flash('Could not fetch Google Trends RSS right now.','error');redirect('trends.php');}if(isset($_GET['refresh'])){db()->exec('DELETE FROM missing_products WHERE LOWER(name) IN (SELECT LOWER(name) FROM stocks)');flash('Missing-product list refreshed against current stock.');redirect('trends.php');}$pageTitle='Trends';$missing=db()->query('SELECT * FROM missing_products ORDER BY checked_at DESC,name')->fetchAll();require 'partials/header.php'; ?><div class="panel"><h1>Trending Products</h1><p>Checks India trending searches from Google Trends RSS and compares them with the inventory names. This is an RSS-based PHP replacement, not the original PyTrends scoring model.</p><a class="btn" href="?check=1">Check Trends</a> <a class="btn" href="?refresh=1">Refresh Missing Products</a><div class="table-wrap"><table><thead><tr><th>Trending term missing in inventory</th><th>Checked at</th></tr></thead><tbody><?php foreach($missing as $m):?><tr><td><?=e($m['name'])?></td><td><?=e($m['checked_at'])?></td></tr><?php endforeach;?></tbody></table></div></div><?php require 'partials/footer.php'; ?>